<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount,onMounted,nextTick} from 'vue'
import {t,formatDate,defaultCover} from '../../../shared/i18n'
import {getUsage} from '../api/detail'
import {coverUrl,loadCovers,uploadCover,selectCover,editCover,type CoverState} from '../api/covers'
const props=defineProps<{workId:string;state?:CoverState}>(),emit=defineEmits<{updated:[state:CoverState];close:[]}>()
const canvas=ref<HTMLCanvasElement>(),image=ref<HTMLImageElement>(),zoom=ref(1),x=ref(50),y=ref(50),busy=ref(false),error=ref(''),prompt=ref(''),source=ref(''),pendingKey=ref(''),pendingSignature=ref(''),unknown=ref(false)
const remaining=ref<number>()
onMounted(()=>{void getUsage().then(v=>remaining.value=v.cover?.dailyRemaining).catch(()=>{})})
const active=computed(()=>props.state?.edits.find(e=>['QUEUED','SUBMITTING','RUNNING','SAVING','SUBMISSION_UNKNOWN'].includes(e.status)))
let objectUrl='',turn=0
function draw(){const target=canvas.value,img=image.value;if(!target||!img)return;const ctx=target.getContext('2d')!;const side=Math.min(img.naturalWidth,img.naturalHeight)/zoom.value;const sx=(img.naturalWidth-side)*x.value/100,sy=(img.naturalHeight-side)*y.value/100;ctx.fillStyle='#fff';ctx.fillRect(0,0,1024,1024);ctx.drawImage(img,sx,sy,side,side,0,0,1024,1024)}
watch([zoom,x,y],draw)
async function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;error.value='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){error.value='请选择10MB以内的JPG、PNG或WebP照片';return}const mine=++turn;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);const img=new Image();try{img.src=objectUrl;await img.decode();if(mine!==turn)return;if(img.naturalWidth*img.naturalHeight>16000000)throw new Error('图片像素过大，请选择1600万像素以内的照片');image.value=img;zoom.value=1;x.value=50;y.value=50;await nextTick();draw()}catch(e){image.value=undefined;error.value=e instanceof Error?e.message:'图片无法读取，请换一张重试'}}
async function apply(id:string|null){if(!props.state)return;busy.value=true;error.value='';try{const state=await selectCover(props.workId,id,props.state.version);emit('updated',state);if(id)source.value=id}catch(e){error.value=e instanceof Error?e.message:'封面应用失败';await refresh()}finally{busy.value=false}}
async function upload(){if(!canvas.value||!props.state)return;busy.value=true;error.value='';try{const blob=await new Promise<Blob>((resolve,reject)=>canvas.value!.toBlob(value=>value?resolve(value):reject(new Error('图片无法读取，请换一张重试')),'image/jpeg',0.9));const asset=await uploadCover(props.workId,blob);source.value=asset.id;const fresh=await loadCovers(props.workId);emit('updated',fresh);const state=await selectCover(props.workId,asset.id,fresh.version);emit('updated',state);image.value=undefined}catch(e){error.value=e instanceof Error?e.message:'封面上传失败';await refresh()}finally{busy.value=false}}
async function refresh(){try{const [state,usage]=await Promise.all([loadCovers(props.workId),getUsage()]);emit('updated',state);remaining.value=usage.cover?.dailyRemaining}catch(e){error.value=e instanceof Error?e.message:'封面读取失败'}}
const keyName=()=>`qingfeng.cover-edit:${props.workId}`
try{const old=JSON.parse(sessionStorage.getItem(keyName())||'null');if(old){pendingKey.value=old.key;pendingSignature.value=old.signature;unknown.value=!!old.unknown}}catch{/* 不依赖本机缓存才能使用普通封面。 */}
async function process(){const id=source.value||props.state?.currentCoverId;if(!id||!prompt.value.trim()||busy.value||active.value)return;busy.value=true;error.value='';const signature=JSON.stringify([id,prompt.value.trim()]);if(pendingSignature.value!==signature){pendingKey.value=crypto.randomUUID();pendingSignature.value=signature;unknown.value=false}pendingKey.value ||= crypto.randomUUID();try{sessionStorage.setItem(keyName(),JSON.stringify({key:pendingKey.value,signature,unknown:true}))}catch{/* 本机缓存不可用时仍保留当前请求键。 */}try{await editCover(props.workId,id,prompt.value.trim(),pendingKey.value);unknown.value=false;pendingKey.value='';try{sessionStorage.removeItem(keyName())}catch{}await refresh()}catch(e){unknown.value=true;error.value=e instanceof Error?e.message:'封面请求结果待核对，请刷新任务'}finally{busy.value=false}}
watch(()=>props.state?.currentCoverId,id=>{if(id&&!source.value)source.value=id},{immediate:true})
onBeforeUnmount(()=>{turn++;if(objectUrl)URL.revokeObjectURL(objectUrl)})
</script>
<template><section class="detail-panel cover-editor" id="cover-editor" tabindex="-1"><div class="detail-heading"><h2>{{ t('让封面，也属于这首歌。') }}</h2><button class="text-button" @click="$emit('close')">{{ t('收起') }}</button></div><p class="detail-muted">{{ t('上传照片直接使用，也可以选择AI加工。更换封面不影响歌曲。') }}</p><p v-if="error" class="notice error" role="alert">{{ t(error) }}</p><label class="file-field">{{ t('选择封面照片') }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="busy" @change="choose"></label><div v-if="image" class="cover-crop"><canvas ref="canvas" width="1024" height="1024" :aria-label="t('封面裁剪预览')"/><div class="cover-crop-controls"><label>{{ t('缩放') }}<input type="range" v-model.number="zoom" min="1" max="3" step="0.01"></label><label>{{ t('水平位置') }}<input type="range" v-model.number="x" min="0" max="100"></label><label>{{ t('垂直位置') }}<input type="range" v-model.number="y" min="0" max="100"></label><button class="button" :disabled="busy||!state" @click="upload">{{ busy?t('正在保存…'):t('裁剪并使用') }}</button></div></div><div v-if="state" class="cover-choices"><button class="cover-choice" :aria-pressed="!state.currentCoverId" :disabled="busy" @click="apply(null)"><img :src="defaultCover()" alt=""><span>{{ t('默认封面') }}</span></button><button v-for="item in state.assets" :key="item.id" class="cover-choice" :aria-pressed="state.currentCoverId===item.id" :disabled="busy" @click="apply(item.id)"><img :src="coverUrl(workId,item.id)" :alt="item.origin==='AI'?t('AI加工封面'):t('上传的封面')"><span>{{ item.origin==='AI'?t('AI加工封面'):t('上传的封面') }}</span></button></div><div class="cover-ai"><h3>{{ t('想给照片一点新意？') }}</h3><p class="save-info">{{ t('点击AI加工会将所选照片发送至KIE图片服务，并使用独立的封面加工额度。原图会保留，满意后再应用。') }}</p><p v-if="state&&!state.aiAvailable" class="notice">{{ t('AI封面暂不可用，可以先使用上传的图片') }}</p><p v-if="remaining!==undefined" class="save-info">{{ remaining<0?t('今日封面加工不限次数'):t('今日还可加工 {remaining} 次封面',{remaining}) }}</p><label class="field">{{ t('封面加工要求') }}<textarea v-model="prompt" maxlength="1000" :disabled="busy||!!active" :placeholder="t('例如：保留人物，做成温暖的胶片封面，不添加文字')"></textarea></label><div class="actions"><button class="button secondary" :disabled="busy||!!active||!state?.aiAvailable||!(source||state.currentCoverId)||!prompt.trim()" @click="process">{{ busy?t('正在处理…'):unknown?t('使用原请求重试'):t('AI加工这张照片') }}</button><button class="text-button" @click="refresh">{{ t('刷新封面任务') }}</button></div><div v-for="edit in state?.edits" :key="edit.id" class="cover-task"><p>{{ t(edit.status==='SUCCEEDED'?'封面已完成，请在上方预览后选择':edit.status==='FAILED'?'这次封面加工未完成，原图仍可使用。':edit.status==='SUBMISSION_UNKNOWN'?'封面结果仍待核对，暂不重复提交':'正在加工封面…') }}</p><small>{{ formatDate(edit.createdAt) }}</small></div></div></section></template>
